{
  "$schema": "https://schemas.opengis.net/ogcapi/processes/part1/1.0/openapi/schemas/process.yaml",
  "id": "EchoProcess",
  "version": "1.0.0",
  "mutable": false,
  "keywords": [
    "builtin"
  ],
  "metadata": [],
  "inputs": {
    "stringInput": {
      "title": "stringInput",
      "minOccurs": 1,
      "maxOccurs": 1,
      "schema": {
        "type": "string",
        "enum": [
          "Value1",
          "Value2",
          "Value3"
        ]
      },
      "literalDataDomains": [
        {
          "default": true,
          "dataType": {
            "name": "string"
          },
          "valueDefinition": [
            "Value1",
            "Value2",
            "Value3"
          ]
        }
      ]
    },
    "measureInput": {
      "title": "Numerical Value with UOM Example",
      "description": "This is an example of a NUMERIC literal with an associated unit of measure.",
      "minOccurs": 1,
      "maxOccurs": 1,
      "schema": {
        "oneOf": [
          {
            "type": "object",
            "required": [
              "measurement",
              "uom"
            ],
            "properties": {
              "measurement": {
                "type": "number"
              },
              "uom": {
                "type": "string",
                "enum": [
                  "m/s²",
                  "km/min²"
                ]
              },
              "reference": {
                "type": "string",
                "format": "uri"
              }
            }
          },
          {
            "type": "number",
            "format": "float"
          }
        ]
      },
      "literalDataDomains": [
        {
          "default": true,
          "dataType": {
            "name": "float"
          },
          "valueDefinition": {
            "anyValue": false
          },
          "UOMs": {
            "supported": [
              {
                "uom": "m/s²"
              },
              {
                "uom": "km/min²"
              }
            ],
            "default": {
              "uom": "m/s²"
            }
          }
        }
      ]
    },
    "dateInput": {
      "title": "Date Literal Input Example",
      "description": "This is an example of a DATE literal input.",
      "minOccurs": 1,
      "maxOccurs": 1,
      "schema": {
        "type": "string",
        "format": "date-time"
      },
      "literalDataDomains": [
        {
          "default": true,
          "dataType": {
            "name": "dateTime"
          },
          "valueDefinition": {
            "anyValue": false
          }
        }
      ]
    },
    "doubleInput": {
      "title": "Bounded Double Literal Input Example",
      "description": "This is an example of a DOUBLE literal input that is bounded between\na value greater than 0 and 10.  The default value is 5.\n",
      "minOccurs": 1,
      "maxOccurs": 1,
      "schema": {
        "type": "number",
        "format": "double"
      },
      "literalDataDomains": [
        {
          "default": true,
          "dataType": {
            "name": "float"
          },
          "valueDefinition": {
            "anyValue": false
          }
        }
      ]
    },
    "arrayInput": {
      "title": "Array Input Example",
      "description": "This is an example of a single process input that is an array of values.\nIn this case, the input array would be interpreted as a single value\nand not as individual inputs.\n",
      "minOccurs": 2,
      "maxOccurs": 10,
      "schema": {
        "type": "array",
        "items": {
          "type": "integer"
        },
        "minItems": 2,
        "maxItems": 10
      },
      "literalDataDomains": [
        {
          "default": true,
          "dataType": {
            "name": "integer"
          },
          "valueDefinition": {
            "anyValue": false
          }
        }
      ]
    },
    "complexObjectInput": {
      "title": "Complex Object Input Example",
      "description": "This is an example of a complex object input.",
      "minOccurs": 1,
      "maxOccurs": 1,
      "schema": {
        "oneOf": [
          {
            "type": "string",
            "contentMediaType": "application/json"
          },
          {
            "type": "object",
            "required": [
              "property1",
              "property5"
            ],
            "properties": {
              "property1": {
                "type": "string"
              },
              "property2": {
                "type": "string",
                "format": "uri"
              },
              "property3": {
                "type": "number"
              },
              "property4": {
                "type": "string",
                "format": "date-time"
              },
              "property5": {
                "type": "boolean"
              }
            }
          }
        ]
      },
      "formats": [
        {
          "default": true,
          "mediaType": "application/json"
        }
      ]
    },
    "geometryInput": {
      "title": "Geometry input",
      "description": "This is an example of a geometry input.\nIn this case the geometry can be expressed as a GML of GeoJSON geometry.\n",
      "minOccurs": 2,
      "maxOccurs": 5,
      "schema": {
        "type": "array",
        "items": {
          "oneOf": [
            {
              "type": "string",
              "contentMediaType": "application/gml+xml; version=3.2",
              "contentSchema": "https://schemas.opengis.net/gml/3.2.1/geometryBasic2d.xsd"
            },
            {
              "type": "string",
              "contentMediaType": "application/json",
              "contentSchema": "http://schemas.opengis.net/ogcapi/features/part1/1.0/openapi/schemas/geometryGeoJSON.yaml"
            },
            {
              "type": "string",
              "format": "binary",
              "contentMediaType": "application/geo+json",
              "contentEncoding": "base64",
              "contentSchema": "https://geojson.org/schema/GeoJSON.json"
            },
            {
              "type": "string",
              "contentMediaType": "application/json",
              "contentSchema": "https://schemas.opengis.net/ogcapi/features/part1/1.0/openapi/schemas/geometryGeoJSON.yaml"
            },
            {
              "allOf": [
                {
                  "format": "geojson-geometry"
                },
                {
                  "$ref": "http://schemas.opengis.net/ogcapi/features/part1/1.0/openapi/schemas/geometryGeoJSON.yaml"
                }
              ]
            }
          ]
        },
        "minItems": 2,
        "maxItems": 5
      },
      "formats": [
        {
          "default": true,
          "mediaType": "application/gml+xml; version=3.2",
          "schema": "https://schemas.opengis.net/gml/3.2.1/geometryBasic2d.xsd"
        },
        {
          "default": false,
          "mediaType": "application/json",
          "schema": "http://schemas.opengis.net/ogcapi/features/part1/1.0/openapi/schemas/geometryGeoJSON.yaml"
        },
        {
          "default": false,
          "mediaType": "application/geo+json",
          "schema": "https://geojson.org/schema/GeoJSON.json"
        },
        {
          "default": false,
          "mediaType": "application/json",
          "schema": "https://schemas.opengis.net/ogcapi/features/part1/1.0/openapi/schemas/geometryGeoJSON.yaml"
        }
      ]
    },
    "boundingBoxInput": {
      "title": "Bounding Box Input Example",
      "description": "This is an example of an image input.\nIn this case, the input is an array of up to 150 images that might,\nfor example, be a set of tiles.  The oneOf[] conditional is used to\nindicate the acceptable image content types; GeoTIFF and JPEG 2000 in\nthis case.  Each input image in the input array can be included inline\nin the execute request as a base64-encoded string or referenced using\nthe link.yaml schema.  The use of a base64-encoded string is implied by\nthe specification and does not need to be specified in the definition \nof the input.\n",
      "minOccurs": 1,
      "maxOccurs": 1,
      "schema": {
        "oneOf": [
          {
            "type": "object",
            "format": "ogc-bbox",
            "required": [
              "bbox"
            ],
            "properties": {
              "crs": {
                "type": "string",
                "format": "uri",
                "default": "http://www.opengis.net/def/crs/OGC/1.3/CRS84",
                "enum": [
                  "epsg:4326"
                ]
              },
              "bbox": {
                "type": "array",
                "items": "number",
                "oneOf": [
                  {
                    "minItems": 4,
                    "maxItems": 4
                  },
                  {
                    "minItems": 6,
                    "maxItems": 6
                  }
                ]
              }
            }
          },
          {
            "type": "string",
            "format": "ogc-bbox",
            "contentSchema": "https://schemas.opengis.net/ogcapi/processes/part1/1.0/openapi/schemas/bbox.yaml"
          }
        ]
      }
    },
    "imagesInput": {
      "title": "Inline Images Value Input",
      "description": "This is an example of an image input.  In this case, the input is\nan array of up to 150 images that might, for example, be a set of tiles.  The\noneOf[] conditional is used to indicate the acceptable image content types;\nGeoTIFF and JPEG 2000 in this case.  Each input image in the input array can\nbe included inline in the execute request as a base64-encoded string or referenced\nusing the link.yaml schema.  The use of a base64-encoded string is implied by\nthe specification and does not need to be specified in the definition of the\ninput.\n",
      "minOccurs": 1,
      "maxOccurs": 150,
      "schema": {
        "oneOf": [
          {
            "type": "string",
            "format": "binary",
            "contentMediaType": "image/tiff; application=geotiff",
            "contentEncoding": "base64"
          },
          {
            "type": "string",
            "format": "binary",
            "contentMediaType": "image/jp2",
            "contentEncoding": "base64"
          },
          {
            "type": "array",
            "items": {
              "oneOf": [
                {
                  "type": "string",
                  "format": "binary",
                  "contentMediaType": "image/tiff; application=geotiff",
                  "contentEncoding": "base64"
                },
                {
                  "type": "string",
                  "format": "binary",
                  "contentMediaType": "image/jp2",
                  "contentEncoding": "base64"
                }
              ]
            },
            "minItems": 1,
            "maxItems": 150
          }
        ]
      },
      "formats": [
        {
          "default": true,
          "mediaType": "image/tiff; application=geotiff",
          "encoding": "base64"
        },
        {
          "default": false,
          "mediaType": "image/jp2",
          "encoding": "base64"
        }
      ]
    },
    "featureCollectionInput": {
      "title": "Feature Collection Input Example",
      "description": "This is an example of an input that is a feature collection that\ncan be encoded in one of three ways. As a GeoJSON feature collection, \nas a GML feature collection retrieved from a WFS or as a KML document.\n",
      "minOccurs": 1,
      "maxOccurs": 1,
      "schema": {
        "oneOf": [
          {
            "type": "string",
            "contentMediaType": "application/gml+xml; version=3.2"
          },
          {
            "type": "string",
            "contentMediaType": "application/vnd.google-earth.kml+xml",
            "contentSchema": "https://schemas.opengis.net/kml/2.3/ogckml23.xsd"
          },
          {
            "type": "string",
            "contentMediaType": "application/json",
            "contentSchema": "https://geojson.org/schema/FeatureCollection.json"
          },
          {
            "type": "string",
            "format": "binary",
            "contentMediaType": "application/geo+json",
            "contentEncoding": "base64",
            "contentSchema": "https://geojson.org/schema/FeatureCollection.json"
          },
          {
            "allOf": [
              {
                "format": "geojson-feature-collection"
              },
              {
                "$ref": "https://geojson.org/schema/FeatureCollection.json"
              }
            ]
          }
        ]
      },
      "formats": [
        {
          "default": true,
          "mediaType": "application/gml+xml; version=3.2"
        },
        {
          "default": false,
          "mediaType": "application/vnd.google-earth.kml+xml",
          "schema": "https://schemas.opengis.net/kml/2.3/ogckml23.xsd"
        },
        {
          "default": false,
          "mediaType": "application/json",
          "schema": "https://geojson.org/schema/FeatureCollection.json"
        },
        {
          "default": false,
          "mediaType": "application/geo+json",
          "schema": "https://geojson.org/schema/FeatureCollection.json"
        }
      ]
    }
  },
  "outputs": {
