                "type": "number"
              },
              "property4": {
                "type": "string",
                "format": "date-time"
              },
              "property5": {
                "type": "boolean"
              }
            }
          }
        ]
      },
      "formats": [
        {
          "default": true,
          "mediaType": "application/json"
        },
        {
          "mediaType": "text/csv"
        },
        {
          "mediaType": "application/xml"
        },
        {
          "mediaType": "application/yaml"
        }
      ]
    },
    "geometryOutput": {
      "title": "geometryOutput",
      "schema": {
        "oneOf": [
          {
            "type": "string",
            "contentMediaType": "application/gml+xml",
            "contentSchema": "http://schemas.opengis.net/gml/3.2.1/geometryBasic2d.xsd"
          },
          {
            "type": "string",
            "contentMediaType": "application/json",
            "contentSchema": "http://schemas.opengis.net/ogcapi/features/part1/1.0/openapi/schemas/geometryGeoJSON.yaml"
          },
