{
  "version": "0.2.0",
  "id": "bgt-land-cover-summary",
  "title": "BKN-oriented BGT land-cover summary",
  "description": "Calculates BKN-oriented land-cover proxies within two circular radii around a WGS 84 coordinate using live PDOK BGT data. The results do not directly measure vegetation height or tree-canopy volume and are not an official BKN assessment.",
  "keywords": [
    "BKN",
    "BGT",
    "PDOK",
    "land cover",
    "Netherlands"
  ],
  "jobControlOptions": [
    "sync-execute"
  ],
  "outputTransmission": [
    "value"
  ],
  "links": [
    {
      "type": "text/html",
      "rel": "about",
      "title": "PDOK BGT API",
      "href": "https://api.pdok.nl/lv/bgt/ogc/v1",
      "hreflang": "nl"
    },
    {
      "type": "text/html",
      "rel": "about",
      "title": "Basiskwaliteit Natuur toolbox",
      "href": "https://www.samenvoorbiodiversiteit.nl/toolbox/basiskwaliteitnatuur",
      "hreflang": "nl"
    },
    {
      "type": "application/json",
      "rel": "self",
      "href": "{{baseUrl}}/processes/bgt-land-cover-summary?f=json",
      "title": "Process description as JSON",
      "hreflang": "en-US"
    },
    {
      "type": "text/html",
      "rel": "alternate",
      "href": "{{baseUrl}}/processes/bgt-land-cover-summary?f=html",
      "title": "Process description as HTML",
      "hreflang": "en-US"
    },
    {
      "type": "text/html",
      "rel": "http://www.opengis.net/def/rel/ogc/1.0/job-list",
      "href": "{{baseUrl}}/jobs?f=html",
      "title": "Jobs list as HTML",
      "hreflang": "en-US"
    },
    {
      "type": "application/json",
      "rel": "http://www.opengis.net/def/rel/ogc/1.0/job-list",
      "href": "{{baseUrl}}/jobs?f=json",
      "title": "Jobs list as JSON",
      "hreflang": "en-US"
    },
    {
      "type": "application/json",
      "rel": "http://www.opengis.net/def/rel/ogc/1.0/execute",
      "href": "{{baseUrl}}/processes/bgt-land-cover-summary/execution?f=json",
      "title": "Execution for this process as JSON",
      "hreflang": "en-US"
    }
  ],
  "inputs": {
    "latitude": {
      "title": "Latitude",
      "description": "WGS 84 latitude in decimal degrees.",
      "schema": {
        "type": "number",
        "minimum": -90,
        "maximum": 90
      },
      "minOccurs": 1,
      "maxOccurs": 1
    },
    "longitude": {
      "title": "Longitude",
      "description": "WGS 84 longitude in decimal degrees.",
      "schema": {
        "type": "number",
        "minimum": -180,
        "maximum": 180
      },
      "minOccurs": 1,
      "maxOccurs": 1
    },
    "inner_radius_m": {
      "title": "Inner radius",
      "description": "Radius in metres for the first complete circular area.",
      "schema": {
        "type": "integer",
        "minimum": 1,
        "maximum": 5000,
        "default": 300
      },
      "minOccurs": 0,
      "maxOccurs": 1
    },
    "outer_radius_m": {
      "title": "Outer radius",
      "description": "Radius in metres for the second complete circular area.",
      "schema": {
        "type": "integer",
        "minimum": 1,
        "maximum": 5000,
        "default": 500
      },
      "minOccurs": 0,
      "maxOccurs": 1
    }
  },
  "outputs": {
    "summary": {
      "title": "BKN-oriented BGT land-cover summary",
      "description": "Percentages, provenance, source diagnostics and execution timings.",
      "schema": {
        "contentMediaType": "application/json",
        "type": "object",
        "required": [
          "process",
          "source",
          "input",
          "is_partial",
          "fetch_failures",
          "classification",
          "timing_seconds",
          "completed_at",
          "within_inner_radius",
